const fav = document.getElementById('btn-fav');
const chk = document.getElementById('expedited-shipping');
const lbl = document.getElementById('shipping-label');
const cart = document.getElementById('btn-add-cart');
const dis = document.getElementById('btn-disabled');
const link = document.getElementById('link-shipping');
if (!dec || !inc || !fav || !chk || !lbl || !cart || !dis || !link) return false;

if (!document.body.classList.contains('ai4a11y-big-targets')) return true;

const decRect = dec.getBoundingClientRect();
const incRect = inc.getBoundingClientRect();
const favRect = fav.getBoundingClientRect();
const chkRect = chk.getBoundingClientRect();
const lblStyle = window.getComputedStyle(lbl);

const decGrown = decRect.width >= 44 && decRect.height >= 44;
const incGrown = incRect.width >= 44 && incRect.height >= 44;
const favGrown = favRect.width >= 44 && favRect.height >= 44;
const chkGrown = chkRect.width >= 24 && chkRect.height >= 24;
const lblClickable = lblStyle.pointerEvents === 'auto';
const linkHasHit = link.hasAttribute('data-ai4a11y-bt') && link.getAttribute('data-ai4a11y-bt').includes('hit');

// Large button (48px high) must NOT be marked grow
const cartMark = cart.getAttribute('data-ai4a11y-bt') || '';
const cartNotGrown = !cartMark.includes('grow');

// Disabled button must not be marked
const disMark = dis.getAttribute('data-ai4a11y-bt') || '';
