const dec = document.getElementById('btn-dec');
const cart = document.getElementById('btn-add-cart');
const navProd = document.getElementById('nav-products');
if (!dec || !cart || !navProd) return false;

if (!document.body.classList.contains('ai4a11y-big-targets')) return true;

function getLuminance(rgbStr) {
  const m = rgbStr.match(/\d+/g);
  if (!m) return null;
  const [r, g, b] = m.slice(0, 3).map(v => {
    const c = Number(v) / 255;
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
function contrast(c1, c2) {
  const l1 = getLuminance(c1);
  const l2 = getLuminance(c2);
  if (l1 === null || l2 === null) return null;
  return (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);
}

// Check focus indicator on button against background
dec.focus();
const decStyle = window.getComputedStyle(dec);
const outlineWidth = parseFloat(decStyle.outlineWidth);
const outlineColor = decStyle.outlineColor;
const ratio = contrast(outlineColor, 'rgb(255, 255, 255)');
dec.blur();

if (outlineWidth < 2 || ratio === null || ratio < 3.0) return false;

// Name matches visible label
if (cart.textContent.trim() !== 'Add to Cart') return false;

return true;

const container = document.getElementById('tight-container');
const desc = document.getElementById('product-desc');
if (!container || !desc) return false;

// Plain text should have no marks
if (desc.hasAttribute('data-ai4a11y-bt')) return false;

if (!document.body.classList.contains('ai4a11y-big-targets')) return true;

// The tight container has fixed width 90px. Growing three buttons to 44px each would require 132px+.
// The adapter must detect overflow and ungrow them, and hit area must not force overflow either.
return container.scrollWidth <= container.clientWidth;
